#!/usr/bin/env python3
"""
Generate the full HTML report for Global Cost of Living Crisis Index 2026
"""

import pandas as pd
import numpy as np
import json
import base64
from io import BytesIO

# Load data
df = pd.read_csv('/app/benchmark/data.csv')

# Load charts
with open('/app/output/charts.json', 'r') as f:
    charts = json.load(f)

# Calculate all KPIs
median_coli = df['cost_of_living_index'].median()
avg_rent_salary = df['rent_to_salary_ratio_pct'].mean()
purchasing_power_gap = df['local_purchasing_power_index'].max() - df['local_purchasing_power_index'].min()
high_crisis_count = len(df[df['cost_crisis_tier'] == df['cost_crisis_tier'].max()])
avg_inflation = df['annual_inflation_rate_2025_pct'].mean()

# Most/Least expensive cities
most_expensive = df.nsmallest(10, 'rank')[['rank', 'city', 'country', 'region', 'cost_of_living_index', 'rent_to_salary_ratio_pct']]
least_expensive = df.nlargest(10, 'rank')[['rank', 'city', 'country', 'region', 'cost_of_living_index', 'rent_to_salary_ratio_pct']]

# Crisis tier summary
tier_summary = df.groupby(['cost_crisis_tier', 'crisis_label']).agg({
    'cost_of_living_index': 'mean',
    'rent_to_salary_ratio_pct': 'mean',
    'local_purchasing_power_index': 'mean',
    'annual_inflation_rate_2025_pct': 'mean',
    'city': 'count'
}).rename(columns={'city': 'city_count'}).round(2).reset_index()

# Regional summary
region_summary = df.groupby('region').agg({
    'cost_of_living_index': ['mean', 'median', 'std'],
    'rent_index': 'mean',
    'local_purchasing_power_index': 'mean',
    'rent_to_salary_ratio_pct': 'mean',
    'annual_inflation_rate_2025_pct': 'mean',
    'avg_monthly_net_salary_usd': 'mean',
    'city': 'count'
}).round(2)
region_summary.columns = ['_'.join(col).strip() for col in region_summary.columns.values]
region_summary = region_summary.sort_values('cost_of_living_index_mean', ascending=False)

# Oil shock exposure summary
oil_summary = df.groupby('oil_shock_exposure').agg({
    'cost_of_living_index': 'mean',
    'annual_inflation_rate_2025_pct': 'mean',
    'local_purchasing_power_index': 'mean',
    'rent_to_salary_ratio_pct': 'mean',
    'city': 'count'
}).rename(columns={'city': 'city_count'}).round(2)

# High rent burden cities
high_rent = df.nlargest(15, 'rent_to_salary_ratio_pct')[['city', 'country', 'rent_to_salary_ratio_pct', 'avg_monthly_net_salary_usd', 'monthly_rent_1br_city_center_usd', 'cost_crisis_tier', 'crisis_label']]

# Inflation analysis
inflation_high = df[df['annual_inflation_rate_2025_pct'] > 10].sort_values('annual_inflation_rate_2025_pct', ascending=False)[['city', 'country', 'annual_inflation_rate_2025_pct', 'crisis_label', 'oil_shock_exposure']]
inflation_low = df[df['annual_inflation_rate_2025_pct'] <= 5].sort_values('annual_inflation_rate_2025_pct')[['city', 'country', 'annual_inflation_rate_2025_pct', 'crisis_label', 'oil_shock_exposure']]

# Affluent vs Crisis comparison
affluent_cities = df[df['cost_crisis_tier'] == 1]
crisis_cities = df[df['cost_crisis_tier'] >= 4]

# Correlations
corr_coli_rent = df['cost_of_living_index'].corr(df['rent_index'])
corr_coli_ppp = df['cost_of_living_index'].corr(df['local_purchasing_power_index'])
corr_rent_salary = df['rent_to_salary_ratio_pct'].corr(df['avg_monthly_net_salary_usd'])
corr_inflation_ppp = df['annual_inflation_rate_2025_pct'].corr(df['local_purchasing_power_index'])

